-- 한남충/니미럴 + 4개 단순 변형어 추가 (2026-09-03, 운영자 지시).
-- 한남충: 김치녀 계열의 남성혐오 비하어, [차별적 비하 표현] 경고.
-- 니미럴: 니애미/느금마 계열의 매우 심한 욕설, [비속어·욕설] 경고.
-- 음원총공/알잘딱/스트리밍/ㅂ2: 기존 단어(총공/알잘딱깔센/스밍/ㅂㅂ)의
-- 단순 변형이지만 운영자 지시로 별도 등재.
--
-- NOTE: 한남충 DE short_desc는 최초 작성 시 자기수정 오타
-- ("Ein frauenfeindliches... nein, männerfeindliches ...")가 들어갔던 것을
-- 커밋 전 execute_sql로 바로잡았다 — 이 파일은 수정된 최종본을 담는다.

begin;

insert into public.slang_candidates (run_id, term, normalized_term, meaning_ko, meaning_en_draft, example, sources, review_note, draft_payload, status) values

(gen_random_uuid(),'한남충','한남충','한국 남성을 벌레에 빗대 비하하는 남성혐오 신조어.','A misandrist slur equating Korean men with insects/vermin.','그 댓글은 한남충이라는 말을 써서 신고당했다.',
 '["https://namu.wiki/w/%ED%95%9C%EB%82%A8%EC%B6%A9"]'::jsonb,
 '명백한 남성혐오 비하어(김치녀의 남성 버전). 성인 게이트 필수. 실제 모욕죄 유죄 판례 있음(벌금 30만원) — origin에 명시. 운영자 직접 지시로 즉시 승격.',
 '{"word":"한남충","romanization":"Han-nam-chung","category":"slang","short_desc":"[차별적 비하 표현] 한국 남성을 벌레에 빗대 비하하는 남성혐오 비하어","short_desc_i18n":{"en":"[Discriminatory slur] A misandrist slur equating Korean men with insects","ja":"[差別的な蔑称] 韓国人男性を虫に例えて蔑む男性蔑視の蔑称","es":"[Término discriminatorio] Insulto misándrico que equipara a hombres coreanos con insectos","vi":"[Từ miệt thị phân biệt] Từ miệt thị đàn ông ví đàn ông Hàn như côn trùng","de":"[Diskriminierendes Schimpfwort] Ein männerfeindliches Schimpfwort, das koreanische Männer mit Insekten gleichsetzt"},"pronunciation":"[한남충]","meanings":[{"type":"비하어(남성혐오)","definition":"''한국 남자''를 줄인 ''한남''과 벌레를 뜻하는 ''충(蟲)''을 합쳐, 한국 남성 전체를 사람이 아닌 벌레처럼 취급하며 비하하는 경멸적 표현. 온라인 극단 커뮤니티에서 생겨나 여러 커뮤니티로 퍼졌다.","definition_i18n":{"en":"Combines ''hannam'' (short for ''Korean man'') with ''chung'' (bug/insect); a contemptuous term that dehumanizes Korean men as vermin rather than people. Originated in an extreme online community and spread to others.","ja":"「韓国男」を略した「한남」と虫を意味する「충（蟲）」を合わせ、韓国人男性全体を人間ではなく虫のように扱って蔑む軽蔑的表現。過激なオンラインコミュニティで生まれ複数のコミュニティに広まった。","es":"Combina ''hannam'' (abreviatura de ''hombre coreano'') con ''chung'' (bicho/insecto); un término despectivo que deshumaniza a los hombres coreanos como alimañas en vez de personas. Se originó en una comunidad en línea extrema y se difundió a otras.","vi":"Ghép ''hannam'' (viết tắt của ''đàn ông Hàn'') với ''chung'' (côn trùng/sâu bọ); từ khinh miệt phi nhân hóa đàn ông Hàn thành sâu bọ thay vì con người. Bắt nguồn từ một cộng đồng mạng cực đoan và lan sang các cộng đồng khác.","de":"Kombiniert ''hannam'' (kurz für ''koreanischer Mann'') mit ''chung'' (Wanze/Insekt); ein verächtlicher Begriff, der koreanische Männer als Ungeziefer statt als Menschen entmenschlicht. Entstand in einer extremen Online-Community und verbreitete sich in andere."},"examples":[{"kor":"그 댓글은 한남충이라는 말을 써서 신고당했다.","eng":"That comment got reported for using the slur ''hannam-chung.''","ja":"あのコメントは「한남충」という言葉を使って通報された。","es":"Ese comentario fue reportado por usar el insulto ''hannam-chung.''","vi":"Bình luận đó bị báo cáo vì dùng từ miệt thị ''hannam-chung.''","de":"Dieser Kommentar wurde wegen der Verwendung des Schimpfworts ''Hannam-chung'' gemeldet."}]}],"origin":"2015년 무렵 남성혐오 성향 커뮤니티 메갈리아에서 만들어져 워마드 등으로 퍼진 표현. 실제로 이 표현을 써 웹툰 작가를 비하한 대학원생이 모욕죄로 벌금 30만원을 선고받은 판례가 있다.","origin_i18n":{"en":"Coined around 2015 on Megalia, a misandrist community, and spread to sites like Womad. A real court case fined a graduate student 300,000 won for insult after using this term to demean a webtoon artist.","ja":"2015年頃、男性蔑視傾向のコミュニティ「メガリア」で作られ、ウォーマドなどに広まった表現。実際にこの言葉を使いウェブトゥーン作家を貶めた大学院生が侮辱罪で罰金30万ウォンを宣告された判例がある。","es":"Acuñado hacia 2015 en Megalia, una comunidad misándrica, y difundido a sitios como Womad. Un caso judicial real multó a un estudiante de posgrado con 300.000 wones por insulto tras usar este término para denigrar a un artista de webtoons.","vi":"Ra đời khoảng năm 2015 trên Megalia, cộng đồng có xu hướng ghét đàn ông, lan sang các trang như Womad. Có án lệ thực tế phạt một nghiên cứu sinh 300.000 won vì tội xúc phạm khi dùng từ này để hạ thấp một họa sĩ webtoon.","de":"Um 2015 auf Megalia geprägt, einer männerfeindlichen Community, und verbreitete sich auf Seiten wie Womad. Ein echter Gerichtsfall verurteilte einen Doktoranden zu einer Geldstrafe von 300.000 Won wegen Beleidigung, nachdem er diesen Begriff verwendet hatte, um einen Webtoon-Künstler herabzuwürdigen."},"usage":"온라인에서 남성을 일반화해 적대·비하할 때 쓰이는 혐오 표현. 실사용 시 모욕죄 등 법적 책임이 따를 수 있으며 사용을 권장하지 않는다.","usage_i18n":{"en":"A hate term used online to generalize and demean men; using it can carry legal liability (e.g. insult charges) and is not recommended.","ja":"オンラインで男性を一般化して敵視・蔑視する際に使われる嫌悪表現。実際の使用は侮辱罪など法的責任を伴う可能性があり推奨されない。","es":"Un término de odio usado en línea para generalizar y denigrar a los hombres; usarlo puede acarrear responsabilidad legal (p. ej. cargos por insulto) y no se recomienda.","vi":"Từ ngữ thù ghét dùng trên mạng để khái quát hóa, hạ thấp đàn ông; dùng có thể chịu trách nhiệm pháp lý (như tội xúc phạm) và không được khuyến khích.","de":"Ein online verwendeter Hassbegriff, um Männer zu verallgemeinern und herabzuwürdigen; die Verwendung kann rechtliche Konsequenzen haben (z. B. Beleidigungsklagen) und wird nicht empfohlen."},"related_words":["김치녀","한남유충"],"translations":[{"lang":"🇺🇸 EN","text":"Misandrist slur for Korean men"},{"lang":"🇯🇵 JA","text":"韓国人男性への男性蔑視の蔑称"},{"lang":"🇨🇳 ZH","text":"针对韩国男性的厌男蔑称"},{"lang":"🇻🇳 VI","text":"Từ miệt thị đàn ông Hàn"},{"lang":"🇪🇸 ES","text":"Insulto misándrico a hombres coreanos"},{"lang":"🇩🇪 DE","text":"Männerfeindliches Schimpfwort"}]}'::jsonb,
 'published'),

(gen_random_uuid(),'니미럴','니미럴','''니 에미랑 붙어먹을''에서 왔다는 설이 있는 매우 심한 욕설.','A severe curse said to derive from an incest-implying insult about one''s mother.','니미럴, 또 놓쳤네.',
 '["https://brunch.co.kr/@jacquestein/49","https://namu.wiki/w/%EC%9A%95%EC%84%A4/%ED%95%9C%EA%B5%AD%EC%96%B4","https://wordrow.kr/%EC%82%AC%ED%88%AC%EB%A6%AC/659378/%EB%8B%88%EB%AF%B8%EB%9F%B4/"]'::jsonb,
 '패드립 계열 중에서도 강도가 매우 센 욕설(어원 자체가 근친 암시). 성인 게이트 필수. 대상 지칭 없이 감탄사로도 쓰여 젠더 이슈는 없으나 표현 자체가 매우 거침. 운영자 직접 지시로 즉시 승격.',
 '{"word":"니미럴","romanization":"Ni-mi-reol","category":"slang","short_desc":"[비속어·욕설] 매우 심한 욕설, 느금마·니애미와 같은 계열","short_desc_i18n":{"en":"[Vulgar/profanity] A very severe curse, in the same family as 느금마/니애미","ja":"[下品な言葉] 非常にきつい罵倒語、느금마・니애미と同系統","es":"[Lenguaje vulgar] Una maldición muy severa, de la misma familia que 느금마/니애미","vi":"[Ngôn ngữ thô tục] Lời chửi rất nặng, cùng họ với 느금마/니애미","de":"[Vulgäre Sprache] Ein sehr schweres Schimpfwort, aus derselben Familie wie 느금마/니애미"},"pronunciation":"[니미럴]","meanings":[{"type":"욕설","definition":"''니 에미랑 붙어먹을''(근친을 암시하는 극단적 모욕)에서 왔다는 설이 유력한 매우 심한 욕설. ''느금마''·''니애미''와 어원 계열이 같지만 표현 강도가 훨씬 세다. 특정 대상 없이 화날 때 혼잣말처럼도 쓰인다.","definition_i18n":{"en":"A very severe curse, most likely derived from an extreme insult implying incest with one''s mother. Shares etymological roots with ''neu-geum-ma'' and ''ni-ae-mi'' but is far more intense. Also blurted alone in anger, without addressing anyone specific.","ja":"「お前の母親と寝る」（近親を仄めかす極端な侮辱）に由来するという説が有力な非常にきつい罵倒語。「느금마」「니애미」と語源系統は同じだが表現の強さははるかに強い。特定の相手がいなくても怒った時に独り言のように使われることもある。","es":"Una maldición muy severa, muy probablemente derivada de un insulto extremo que implica incesto con la propia madre. Comparte raíces etimológicas con ''neu-geum-ma'' y ''ni-ae-mi'' pero es mucho más intensa. También se suelta a solas con enfado, sin dirigirse a nadie en particular.","vi":"Lời chửi rất nặng, có khả năng bắt nguồn từ lời sỉ nhục cực đoan ám chỉ loạn luân với mẹ mình. Cùng gốc từ nguyên với ''neu-geum-ma'' và ''ni-ae-mi'' nhưng mạnh hơn nhiều. Cũng được buột miệng một mình khi tức giận, không nhắm vào ai cụ thể.","de":"Ein sehr schweres Schimpfwort, höchstwahrscheinlich abgeleitet von einer extremen Beleidigung, die Inzest mit der eigenen Mutter unterstellt. Teilt etymologische Wurzeln mit ''Neu-geum-ma'' und ''Ni-ae-mi'', ist aber weit intensiver. Wird auch allein vor Wut herausgeplatzt, ohne sich an jemand Bestimmtes zu richten."},"examples":[{"kor":"니미럴, 또 놓쳤네.","eng":"Damn it, missed it again.","ja":"くそっ、また逃した。","es":"Maldición, lo perdí otra vez.","vi":"Chết tiệt, lại lỡ nữa rồi.","de":"Verdammt, wieder verpasst."}]}],"origin":"어원은 불명확하나 ''니 에미랑 붙어먹을''을 줄인 표현이라는 설이 가장 유력하며, ''느금마''(느그 어미)·''니기미'' 등과 발음이 비슷한 계열의 패드립 욕설로 분류된다.","origin_i18n":{"en":"The exact origin is unclear, but the most widely cited theory shortens ''sleeping with your own mother'' (an incest-implying insult); classified alongside similarly-sounding parent-insult profanities like ''neu-geum-ma'' and ''ni-gi-mi.''","ja":"語源は不明確だが、「お前の母親と寝る」を略した表現という説が最も有力とされ、「느금마」「니기미」など発音の似た系統の親罵倒語に分類される。","es":"El origen exacto no está claro, pero la teoría más citada lo abrevia de ''acostarse con tu propia madre'' (un insulto que implica incesto); se clasifica junto a maldiciones de insulto a los padres de sonido similar como ''neu-geum-ma'' y ''ni-gi-mi.''","vi":"Nguồn gốc chính xác chưa rõ, nhưng giả thuyết được trích dẫn nhiều nhất rút gọn từ ''ngủ với mẹ mình'' (lời sỉ nhục ám chỉ loạn luân); được xếp cùng nhóm các từ chửi cha mẹ phát âm tương tự như ''neu-geum-ma'' và ''ni-gi-mi.''","de":"Der genaue Ursprung ist unklar, aber die meistzitierte Theorie verkürzt ''mit der eigenen Mutter schlafen'' (eine Inzest unterstellende Beleidigung); wird zusammen mit ähnlich klingenden Elternbeleidigungs-Schimpfwörtern wie ''Neu-geum-ma'' und ''Ni-gi-mi'' eingeordnet."},"usage":"매우 격하게 화나거나 짜증 날 때 내뱉는 욕설로, 어원을 알면 절대 가볍게 쓸 말이 아니다. 공식적·정중한 자리에선 절대 쓰지 않는다.","usage_i18n":{"en":"A profanity blurted out in extreme anger or frustration; knowing its origin, it should never be used lightly. Never used in formal or polite settings.","ja":"非常に激しく怒ったりイライラした時に吐く罵倒語で、語源を知れば決して軽く使う言葉ではない。フォーマルな場では絶対に使わない。","es":"Una palabrota que se suelta en enfado o frustración extremos; conociendo su origen, nunca debería usarse a la ligera. Nunca en contextos formales o educados.","vi":"Lời chửi buột ra khi cực kỳ tức giận hay bực bội; biết nguồn gốc thì tuyệt đối không nên dùng nhẹ nhàng. Không bao giờ dùng ở nơi trang trọng, lịch sự.","de":"Ein Schimpfwort, das bei extremer Wut oder Frustration herausplatzt; wer den Ursprung kennt, sollte es niemals leichtfertig verwenden. Niemals in formellen oder höflichen Situationen."},"related_words":["느금마","니애미"],"translations":[{"lang":"🇺🇸 EN","text":"Damn it (severe curse)"},{"lang":"🇯🇵 JA","text":"くそったれ（強い罵倒語）"},{"lang":"🇨🇳 ZH","text":"极粗俗的脏话"},{"lang":"🇻🇳 VI","text":"Chết tiệt (chửi nặng)"},{"lang":"🇪🇸 ES","text":"Maldición (muy fuerte)"},{"lang":"🇩🇪 DE","text":"Verdammt (schweres Schimpfwort)"}]}'::jsonb,
 'published'),

(gen_random_uuid(),'음원총공','음원총공','음원 순위를 위해 팬덤이 총공(집중 스트리밍)하는 것.','A K-pop fandom''s coordinated mass-streaming push specifically for chart rankings.','컴백 첫날 음원총공 필수야.',
 '["https://namu.wiki/w/%EC%B4%9D%EA%B3%B5"]'::jsonb,
 '''총공''의 음원 특화 변형. 이미 있는 단어의 단순 변형이지만 운영자 지시로 추가.',
 '{"word":"음원총공","romanization":"Eum-won-chong-gong","category":"kpop","short_desc":"음원 순위를 위한 팬덤의 총공(집중 스트리밍)","short_desc_i18n":{"en":"A fandom''s coordinated streaming push for chart rankings","ja":"音源ランキングのためのファンダムの総攻（集中ストリーミング）","es":"Un empuje coordinado de streaming del fandom para los rankings","vi":"Đợt stream đồng loạt của fandom nhắm bảng xếp hạng nhạc","de":"Eine koordinierte Streaming-Offensive einer Fandom für Chart-Rankings"},"pronunciation":"[음원총공]","meanings":[{"type":"팬덤 용어","definition":"''총공''(총공격) 중에서도 특히 음원 스트리밍·차트 순위에 화력을 집중하는 것을 콕 집어 이르는 말. ''총공''의 세부 변형이다.","definition_i18n":{"en":"A specific subset of ''chong-gong'' (all-out fan push) that concentrates firepower specifically on music streaming and chart rankings.","ja":"「총공」（総攻撃）の中でも特に音源ストリーミング・チャート順位に火力を集中することを指す語。「총공」の細分化された変形。","es":"Un subconjunto específico de ''chong-gong'' (empuje total de fans) que concentra el poder de fuego específicamente en streaming musical y rankings de listas.","vi":"Một nhánh cụ thể của ''chong-gong'' (tổng công fan) dồn hỏa lực riêng vào streaming nhạc và bảng xếp hạng.","de":"Eine spezifische Untergruppe von ''Chong-gong'' (Fan-Gesamtoffensive), die Feuerkraft speziell auf Musik-Streaming und Chart-Rankings konzentriert."},"examples":[{"kor":"컴백 첫날 음원총공 필수야.","eng":"Streaming push is a must on comeback day.","ja":"カムバ初日は音源총공必須だよ。","es":"El empuje de streaming es obligatorio el día del comeback.","vi":"Ngày đầu comeback phải cày stream tổng công đấy.","de":"Am Comeback-Tag ist die Streaming-Offensive Pflicht."}]}],"origin":"''총공''에서 파생된 세부 용어로, 음원 스트리밍에 특화된 팬덤 활동을 가리키기 위해 만들어졌다.","origin_i18n":{"en":"A derived subset term of ''chong-gong,'' coined to specify fandom activity focused on music streaming.","ja":"「총공」から派生した細分用語で、音源ストリーミングに特化したファンダム活動を指すために作られた。","es":"Un término derivado de ''chong-gong,'' acuñado para especificar la actividad de fandom enfocada en streaming musical.","vi":"Thuật ngữ phái sinh từ ''chong-gong'', ra đời để chỉ hoạt động fandom tập trung vào streaming nhạc.","de":"Ein abgeleiteter Begriff von ''Chong-gong'', geprägt, um Fandom-Aktivitäten zu bezeichnen, die sich auf Musik-Streaming konzentrieren."},"usage":"음원차트 순위 경쟁 시기에 스트리밍에 집중하자고 독려할 때 쓴다.","usage_i18n":{"en":"Used to rally fans to focus on streaming during chart-ranking competition periods.","ja":"音源チャート順位競争の時期にストリーミングに集中しようと呼びかける時に使う。","es":"Se usa para reunir a los fans para enfocarse en streaming durante períodos de competencia de rankings.","vi":"Dùng để kêu gọi fan tập trung stream trong giai đoạn cạnh tranh bảng xếp hạng.","de":"Wird verwendet, um Fans dazu aufzurufen, sich während Chart-Ranking-Wettbewerbszeiten auf Streaming zu konzentrieren."},"related_words":["총공","스밍"],"translations":[{"lang":"🇺🇸 EN","text":"Streaming push"},{"lang":"🇯🇵 JA","text":"音源総攻"},{"lang":"🇨🇳 ZH","text":"打歌刷榜"},{"lang":"🇻🇳 VI","text":"Cày stream tổng công"},{"lang":"🇪🇸 ES","text":"Empuje de streaming"},{"lang":"🇩🇪 DE","text":"Streaming-Offensive"}]}'::jsonb,
 'published'),

(gen_random_uuid(),'알잘딱','알잘딱','''알잘딱깔센''의 축약형, 같은 뜻으로 더 자주 쓰인다.','The shortened form of ''al-jal-ttak-kkal-sen,'' now used more often than the full phrase.','그거 알잘딱 처리해줘.',
 '["https://yulbin.com/%EC%95%8C%EC%9E%98%EB%94%B1%EA%B9%94%EC%84%BC-%EB%9C%BB%EA%B3%BC-%EC%9C%A0%EB%9E%98-%EC%95%8C%EC%9E%98%EB%94%B1-%EB%9C%BB/"]'::jsonb,
 '''알잘딱깔센''의 단순 축약형. 운영자 지시로 추가.',
 '{"word":"알잘딱","romanization":"Al-jal-ttak","category":"daily","short_desc":"''알잘딱깔센''의 축약형","short_desc_i18n":{"en":"The shortened form of ''al-jal-ttak-kkal-sen''","ja":"「알잘딱깔센」の短縮形","es":"La forma abreviada de ''al-jal-ttak-kkal-sen''","vi":"Dạng rút gọn của ''al-jal-ttak-kkal-sen''","de":"Die verkürzte Form von ''al-jal-ttak-kkal-sen''"},"pronunciation":"[알잘딱]","meanings":[{"type":"인터넷 유행어","definition":"''알아서 잘 딱 깔끔하고 센스있게''를 줄인 ''알잘딱깔센''을 한 번 더 줄인 말. 뜻은 완전히 같으며, 실제로는 이 축약형이 원형보다 더 자주 쓰인다.","definition_i18n":{"en":"A further shortening of ''al-jal-ttak-kkal-sen'' (handle it well, cleanly, with sense). The meaning is identical, and in practice this shorter form is used more often than the full phrase.","ja":"「알아서 잘 딱 깔끔하고 센스있게」を略した「알잘딱깔센」をさらに略した語。意味は全く同じで、実際にはこの短縮形の方が原形より頻繁に使われる。","es":"Una abreviación adicional de ''al-jal-ttak-kkal-sen'' (manéjalo bien, limpio, con estilo). El significado es idéntico, y en la práctica esta forma corta se usa más que la frase completa.","vi":"Rút gọn thêm từ ''al-jal-ttak-kkal-sen'' (tự xử lý tốt, gọn gàng, tinh tế). Nghĩa hoàn toàn giống, và thực tế dạng ngắn này dùng nhiều hơn cả bản đầy đủ.","de":"Eine weitere Verkürzung von ''al-jal-ttak-kkal-sen'' (gut, sauber, mit Gespür erledigen). Die Bedeutung ist identisch, und in der Praxis wird diese kürzere Form häufiger verwendet als die vollständige Phrase."},"examples":[{"kor":"그거 알잘딱 처리해줘.","eng":"Handle that perfectly, you know how.","ja":"それ알잘딱でやっといて。","es":"Encárgate de eso perfectamente, ya sabes cómo.","vi":"Cái đó tự xử lý khéo giúp mình nhé.","de":"Erledige das bitte perfekt, du weißt schon wie."}]}],"origin":"''알잘딱깔센''이 일상 대화에서 더 짧게 줄어 쓰이며 자리 잡은 축약형이다.","origin_i18n":{"en":"An abbreviation that emerged as ''al-jal-ttak-kkal-sen'' got shortened further in everyday conversation.","ja":"「알잘딱깔센」が日常会話でさらに短く縮まって定着した略語。","es":"Una abreviación que surgió cuando ''al-jal-ttak-kkal-sen'' se acortó aún más en la conversación cotidiana.","vi":"Từ viết tắt xuất hiện khi ''al-jal-ttak-kkal-sen'' được rút gọn thêm trong trò chuyện đời thường.","de":"Eine Abkürzung, die entstand, als ''al-jal-ttak-kkal-sen'' im Alltagsgespräch weiter verkürzt wurde."},"usage":"''알잘딱깔센''과 완전히 같은 뜻·용법으로, 더 캐주얼하고 빠르게 말할 때 쓴다.","usage_i18n":{"en":"Used with the exact same meaning and usage as ''al-jal-ttak-kkal-sen,'' just more casual and quicker to say.","ja":"「알잘딱깔센」と全く同じ意味・用法で、よりカジュアルに手早く言いたい時に使う。","es":"Se usa con el mismo significado y uso exacto que ''al-jal-ttak-kkal-sen,'' solo más casual y rápido de decir.","vi":"Dùng với nghĩa và cách dùng y hệt ''al-jal-ttak-kkal-sen'', chỉ là nói nhanh, thoải mái hơn.","de":"Wird mit genau derselben Bedeutung und Verwendung wie ''al-jal-ttak-kkal-sen'' verwendet, nur lässiger und schneller zu sagen."},"related_words":["알잘딱깔센"],"translations":[{"lang":"🇺🇸 EN","text":"Handle it perfectly (short form)"},{"lang":"🇯🇵 JA","text":"うまくセンス良く（短縮形）"},{"lang":"🇨🇳 ZH","text":"机灵妥当（简称）"},{"lang":"🇻🇳 VI","text":"Tự xử lý khéo (rút gọn)"},{"lang":"🇪🇸 ES","text":"Resuélvelo con estilo (corto)"},{"lang":"🇩🇪 DE","text":"Perfekt erledigen (Kurzform)"}]}'::jsonb,
 'published'),

(gen_random_uuid(),'스트리밍','스트리밍','음원·영상을 실시간 재생하는 것, ''스밍''의 본말.','''Streaming'' — the full, unabbreviated form of ''seu-ming.''','요즘은 다운로드보다 스트리밍이 대세야.',
 '["https://www.wowtv.co.kr/NewsCenter/News/Read?articleId=A201602230607"]'::jsonb,
 '''스밍''의 본말. 운영자 지시로 추가.',
 '{"word":"스트리밍","romanization":"Seu-teu-ri-ming","category":"kpop","short_desc":"''스밍''의 본말, 음원·영상 실시간 재생","short_desc_i18n":{"en":"''Streaming'' — the full form of ''seu-ming''","ja":"「스밍」の元の形、音源・映像のリアルタイム再生","es":"''Streaming'' — la forma completa de ''seu-ming''","vi":"''Streaming'' — dạng đầy đủ của ''seu-ming''","de":"''Streaming'' — die vollständige Form von ''seu-ming''"},"pronunciation":"[스트리밍]","meanings":[{"type":"팬덤·인터넷 용어","definition":"영어 ''streaming''을 그대로 옮긴 말로, 음원이나 영상을 다운로드 없이 실시간으로 재생하는 것을 이른다. 팬덤 맥락에서 줄여 부를 때는 ''스밍''이라 한다.","definition_i18n":{"en":"A direct borrowing of the English ''streaming''; refers to playing music or video in real time without downloading. In fandom contexts, it''s shortened to ''seu-ming.''","ja":"英語「streaming」をそのまま取った語で、音源や映像をダウンロードなしにリアルタイムで再生することを指す。ファンダムの文脈で略す時は「스밍」と言う。","es":"Un préstamo directo del inglés ''streaming''; se refiere a reproducir música o video en tiempo real sin descargar. En contextos de fandom, se abrevia ''seu-ming.''","vi":"Vay mượn trực tiếp từ ''streaming'' tiếng Anh; chỉ việc phát nhạc, video trực tiếp không cần tải xuống. Trong ngữ cảnh fandom, rút gọn thành ''seu-ming.''","de":"Eine direkte Übernahme des englischen ''Streaming''; bezieht sich auf das Abspielen von Musik oder Video in Echtzeit ohne Download. Im Fandom-Kontext wird es zu ''seu-ming'' verkürzt."},"examples":[{"kor":"요즘은 다운로드보다 스트리밍이 대세야.","eng":"Streaming is more mainstream than downloading these days.","ja":"最近はダウンロードよりストリーミングが主流だよ。","es":"Hoy en día el streaming es más común que descargar.","vi":"Dạo này streaming phổ biến hơn tải xuống rồi.","de":"Heutzutage ist Streaming üblicher als Herunterladen."}]}],"origin":"영어 ''streaming''이 그대로 한국어에 들어온 외래어로, 음악·영상 서비스 확산과 함께 일상어로 정착했다. 팬덤에서는 줄여 ''스밍''으로 쓴다.","origin_i18n":{"en":"A loanword directly imported from English ''streaming,'' settled into everyday use as music/video services spread. Fandoms shorten it to ''seu-ming.''","ja":"英語「streaming」がそのまま韓国語に入った外来語で、音楽・映像サービスの普及と共に日常語として定着した。ファンダムでは略して「스밍」と使う。","es":"Un préstamo importado directamente del inglés ''streaming,'' asentado en el uso cotidiano a medida que se difundían los servicios de música/video. Los fandoms lo abrevian ''seu-ming.''","vi":"Từ mượn nhập trực tiếp từ ''streaming'' tiếng Anh, định hình trong dùng hàng ngày khi dịch vụ nhạc/video lan rộng. Fandom rút gọn thành ''seu-ming.''","de":"Ein Lehnwort, direkt aus dem englischen ''Streaming'' importiert, das sich im Alltagsgebrauch etablierte, während sich Musik-/Videodienste verbreiteten. Fandoms kürzen es zu ''seu-ming''."},"usage":"음악·영상을 실시간 재생하는 일반적 상황 전반에서 널리 쓴다.","usage_i18n":{"en":"Widely used for any general situation of playing music or video in real time.","ja":"音楽・映像をリアルタイムで再生する一般的な状況全般で広く使う。","es":"Ampliamente usado para cualquier situación general de reproducir música o video en tiempo real.","vi":"Dùng rộng rãi cho mọi tình huống chung về phát nhạc, video theo thời gian thực.","de":"Wird breit für jede allgemeine Situation des Echtzeit-Abspielens von Musik oder Video verwendet."},"related_words":["스밍"],"translations":[{"lang":"🇺🇸 EN","text":"Streaming"},{"lang":"🇯🇵 JA","text":"ストリーミング"},{"lang":"🇨🇳 ZH","text":"流媒体播放"},{"lang":"🇻🇳 VI","text":"Streaming"},{"lang":"🇪🇸 ES","text":"Streaming"},{"lang":"🇩🇪 DE","text":"Streaming"}]}'::jsonb,
 'published'),

(gen_random_uuid(),'ㅂ2','ㅂ2','숫자 2를 ''이''로 읽어 ''바이''처럼 들리게 만든 작별 인사 표현.','A stylized ''bye'' using the consonant ㅂ plus the digit 2 (read ''i,'' sounding like ''bai'').','나 먼저 갈게, ㅂ2',
 '["https://namu.wiki/w/%EC%B4%88%EC%84%B1%EC%B2%B4/%EB%AA%A9%EB%A1%9D"]'::jsonb,
 '''ㅂㅂ''의 숫자 변형. 운영자 지시로 추가.',
 '{"word":"ㅂ2","romanization":"B-2","category":"consonant","short_desc":"숫자 2로 ''바이''처럼 들리게 만든 작별 인사","short_desc_i18n":{"en":"A stylized ''bye'' using ㅂ plus the digit 2","ja":"数字2で「バイ」のように聞こえる別れの挨拶","es":"Un ''adiós'' estilizado usando ㅂ más el dígito 2","vi":"Lời tạm biệt cách điệu dùng ㅂ với số 2","de":"Ein stilisiertes ''Tschüss'' mit ㅂ plus der Ziffer 2"},"pronunciation":"[비투]","meanings":[{"type":"초성체","definition":"자음 ''ㅂ''에 숫자 ''2''(한글로 ''이''라 읽음)를 붙여 ''바이(bye)''처럼 들리게 만든 말장난식 작별 인사. ''ㅂㅂ''과 뜻은 같다.","definition_i18n":{"en":"A wordplay farewell combining the consonant ''ㅂ'' with the digit ''2'' (read as ''i'' in Korean), together sounding like ''bai'' (bye). Means the same as ''ㅂㅂ.''","ja":"子音「ㅂ」に数字「2」（韓国語で「イ」と読む）を付け「バイ（bye）」のように聞こえるようにした語呂合わせの別れの挨拶。「ㅂㅂ」と意味は同じ。","es":"Una despedida de juego de palabras que combina la consonante ''ㅂ'' con el dígito ''2'' (se lee ''i'' en coreano), sonando juntos como ''bai'' (bye). Significa lo mismo que ''ㅂㅂ.''","vi":"Lời tạm biệt chơi chữ kết hợp phụ âm ''ㅂ'' với số ''2'' (đọc là ''i'' trong tiếng Hàn), nghe như ''bai'' (bye). Nghĩa giống ''ㅂㅂ.''","de":"Ein Wortspiel-Abschied, der den Konsonanten ''ㅂ'' mit der Ziffer ''2'' (im Koreanischen als ''i'' gelesen) kombiniert, zusammen klingt es wie ''bai'' (bye). Bedeutet dasselbe wie ''ㅂㅂ.''"},"examples":[{"kor":"나 먼저 갈게, ㅂ2","eng":"I''m heading out first, bai~","ja":"先に行くね、ばい2","es":"Me voy primero, bai~","vi":"Mình đi trước nha, bai~","de":"Ich geh schon mal, bai~"}]}],"origin":"''ㅂㅂ''과 같은 뜻이지만, 숫자 ''2''의 한글 발음 ''이''를 이용해 ''바이''와 더 비슷하게 들리도록 만든 말장난에서 나왔다.","origin_i18n":{"en":"Means the same as ''ㅂㅂ,'' but arose as a pun using the Korean pronunciation of ''2'' (''i'') to sound even closer to ''bai'' (bye).","ja":"「ㅂㅂ」と同じ意味だが、数字「2」の韓国語発音「イ」を利用して「バイ」により似せた語呂合わせから生まれた。","es":"Significa lo mismo que ''ㅂㅂ,'' pero surgió como un juego de palabras usando la pronunciación coreana de ''2'' (''i'') para sonar aún más parecido a ''bai'' (bye).","vi":"Nghĩa giống ''ㅂㅂ'', nhưng ra đời như trò chơi chữ dùng cách đọc tiếng Hàn của số ''2'' (''i'') để nghe càng giống ''bai'' (bye) hơn.","de":"Bedeutet dasselbe wie ''ㅂㅂ'', entstand aber als Wortspiel, das die koreanische Aussprache von ''2'' (''i'') nutzt, um noch näher an ''bai'' (bye) zu klingen."},"usage":"''ㅂㅂ''과 같은 상황에서, 좀 더 귀엽고 장난스러운 느낌으로 쓴다.","usage_i18n":{"en":"Used in the same situations as ''ㅂㅂ,'' but with a cuter, more playful feel.","ja":"「ㅂㅂ」と同じ状況で、より可愛らしく茶目っ気のある感じで使う。","es":"Se usa en las mismas situaciones que ''ㅂㅂ,'' pero con un toque más tierno y juguetón.","vi":"Dùng trong tình huống giống ''ㅂㅂ'', nhưng mang cảm giác dễ thương, tinh nghịch hơn.","de":"Wird in denselben Situationen wie ''ㅂㅂ'' verwendet, aber mit einem niedlicheren, verspielteren Gefühl."},"related_words":["ㅂㅂ"],"translations":[{"lang":"🇺🇸 EN","text":"Bai~"},{"lang":"🇯🇵 JA","text":"ばい2"},{"lang":"🇨🇳 ZH","text":"拜拜（谐音）"},{"lang":"🇻🇳 VI","text":"Bai~"},{"lang":"🇪🇸 ES","text":"Bai~"},{"lang":"🇩🇪 DE","text":"Bai~"}]}'::jsonb,
 'published');

insert into public.words (id, word, romanization, category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations)
select
  (180 + row_number() over (order by created_at))::text,
  dp->>'word', dp->>'romanization', dp->>'category', dp->>'short_desc', dp->'short_desc_i18n',
  dp->>'pronunciation', dp->'meanings', dp->>'origin', dp->'origin_i18n', dp->>'usage', dp->'usage_i18n',
  array(select jsonb_array_elements_text(dp->'related_words')), 0, 0, dp->'translations'
from (
  select draft_payload as dp, created_at
  from public.slang_candidates
  where term in ('한남충','니미럴','음원총공','알잘딱','스트리밍','ㅂ2') and status='published'
) t
order by created_at;

commit;
